-- Runs on an admin connection. All data, coin and history changes ROLLBACK.
begin;
do $$
declare
 admin_user public.users; reader public.users; outsider public.users;
 aid uuid:=gen_random_uuid(); reward_id uuid:=gen_random_uuid(); invite_id uuid:=gen_random_uuid();
 draft jsonb; result jsonb; balance integer; n integer; rejected boolean;
begin
 select * into admin_user from public.users where role='admin' and auth_user_id is not null and is_active and not coalesce(is_banned,false) limit 1;
 select * into reader from public.users where username='denemeuser' and auth_user_id is not null;
 select * into outsider from public.users where role='user' and id<>reader.id and auth_user_id is not null and is_active and not coalesce(is_banned,false) limit 1;
 if admin_user.id is null or reader.id is null or outsider.id is null then raise exception 'Test için yönetici ve iki mevcut test hesabı gerekli.'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_user.auth_user_id,'role','authenticated','session_id',coalesce(admin_user.active_session_id,gen_random_uuid()))::text,true);
 if app_private.current_public_user_id() is distinct from admin_user.id then raise exception 'Yönetici test oturumu çözülemedi.'; end if;
 draft:=jsonb_build_object('title','Okuma buluşması — doğrulama','document',jsonb_build_array(jsonb_build_object('type','text','text','**Birlikte okuyalım.** ==Yeni bölüm==')),
 'kind','news','status','draft','audience','selected','startsAt',now()-interval '1 minute','endsAt',now()+interval '1 day','priority',5,'showHome',true,'action',jsonb_build_object('type','none'),'recipients',jsonb_build_array(reader.id));
 result:=public.announcement_admin_save(aid,0,draft);
 if result->>'status'<>'draft' or (result->>'revision')::int<>1 then raise exception 'Taslak kaydı başarısız.'; end if;
 if jsonb_array_length(public.announcement_feed(aid,false,0,20,null))<>0 then raise exception 'Taslak yayına sızdı.'; end if;
 rejected:=false; begin perform public.announcement_admin_save(aid,0,draft); exception when serialization_failure then rejected:=true; end;
 if not rejected then raise exception 'Eski sürüm yazımı engellenmedi.'; end if;
 draft:=jsonb_set(draft,'{status}','"published"'); result:=public.announcement_admin_save(aid,1,draft);
 perform set_config('request.jwt.claims','{"role":"anon"}',true);
 if jsonb_array_length(public.announcement_feed(aid,false,0,20,null))<>0 then raise exception 'Özel duyuru anonime sızdı.'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider.auth_user_id,'role','authenticated','session_id',coalesce(outsider.active_session_id,gen_random_uuid()))::text,true);
 if jsonb_array_length(public.announcement_feed(aid,false,0,20,null))<>0 then raise exception 'Özel duyuru başka hesaba sızdı.'; end if;
 rejected:=false; begin perform public.announcement_admin_list(); exception when insufficient_privilege then rejected:=true; end;
 if not rejected then raise exception 'Yönetici okuması korunmuyor.'; end if;
 rejected:=false; begin perform public.announcement_respond(aid,'view'); exception when insufficient_privilege then rejected:=true; end;
 if not rejected then raise exception 'Görüntüleme yetkisi korunmuyor.'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',reader.auth_user_id,'role','authenticated','session_id',coalesce(reader.active_session_id,gen_random_uuid()))::text,true);
 if jsonb_array_length(public.announcement_feed(aid,false,0,20,null))<>1 then raise exception 'Alıcı duyurusunu göremedi.'; end if;
 perform public.announcement_respond(aid,'view'); perform public.announcement_respond(aid,'view');
 select count(*) into n from announcement_internal.responses where announcement_id=aid;
 if n<>1 then raise exception 'Görüntüleme tekrarında sayaç arttı.'; end if;
 update announcement_internal.entries set starts_at=now()+interval '1 hour' where id=aid;
 if jsonb_array_length(public.announcement_feed(aid,false,0,20,null))<>0 then raise exception 'Planlı duyuru erken göründü.'; end if;
 update announcement_internal.entries set starts_at=now()-interval '2 days',ends_at=now()-interval '1 day' where id=aid;
 if jsonb_array_length(public.announcement_feed(aid,false,0,20,null))<>0 then raise exception 'Süresi dolmuş duyuru göründü.'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_user.auth_user_id,'role','authenticated','session_id',coalesce(admin_user.active_session_id,gen_random_uuid()))::text,true);
 draft:=draft||jsonb_build_object('kind','reward','audience','members','recipients','[]'::jsonb,'action',jsonb_build_object('type','reward','value',17,'maxClaims',1));
 result:=public.announcement_admin_save(reward_id,0,draft);
 if not (result->>'rewardLocked')::boolean then raise exception 'Ödül havuzu oluşmadı.'; end if;
 rejected:=false; begin perform public.announcement_admin_save(reward_id,1,jsonb_set(draft,'{action,value}','18')); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Yayımlanmış ödül değişti.'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',reader.auth_user_id,'role','authenticated','session_id',coalesce(reader.active_session_id,gen_random_uuid()))::text,true);
 select stones into balance from public.users where id=reader.id;
 result:=public.announcement_respond(reward_id,'claim');
 if result ?| array['code','code_id'] then raise exception 'Özel ödül kodu sızdı.'; end if;
 if (result->>'new_balance')::integer<>balance+17 then raise exception 'Coin bakiyesi doğru artmadı.'; end if;
 result:=public.announcement_respond(reward_id,'claim');
 if not (result->>'alreadyClaimed')::boolean then raise exception 'Ödül tekrarı tekilleştirilmedi.'; end if;
 if (select stones from public.users where id=reader.id)<>balance+17 then raise exception 'Tekrar istek ikinci ödeme yaptı.'; end if;
 rejected:=false; begin update public.users set stones=stones+1 where id=reader.id; exception when others then rejected:=true; end;
 if not rejected then raise exception 'Tek kullanımlık izin ödül dışı bakiye güncellemesine sızdı.'; end if;
 if exists(select 1 from announcement_internal.wallet_permits) then raise exception 'Tüketilmemiş bakiye izni kaldı.'; end if;
 if has_function_privilege('authenticated','announcement_internal.consume_wallet_permit(public.users,public.users)','EXECUTE') then raise exception 'İstemciye bakiye izni açık.'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider.auth_user_id,'role','authenticated','session_id',coalesce(outsider.active_session_id,gen_random_uuid()))::text,true);
 rejected:=false; begin perform public.announcement_respond(reward_id,'claim'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Ödül bütçesi aşıldı.'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',admin_user.auth_user_id,'role','authenticated','session_id',coalesce(admin_user.active_session_id,gen_random_uuid()))::text,true);
 draft:=draft||jsonb_build_object('kind','invitation','audience','selected','recipients',jsonb_build_array(reader.id),'action',jsonb_build_object('type','rsvp'));
 perform public.announcement_admin_save(invite_id,0,draft);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',reader.auth_user_id,'role','authenticated','session_id',coalesce(reader.active_session_id,gen_random_uuid()))::text,true);
 perform public.announcement_respond(invite_id,'accepted');
 rejected:=false; begin perform public.announcement_respond(invite_id,'declined'); exception when serialization_failure then rejected:=true; end;
 if not rejected or (public.announcement_feed(invite_id,false,0,1,null)->0->>'response')<>'accepted' then raise exception 'İlk davet yanıtı kilitlenmedi.'; end if;
 rejected:=false; begin perform public.announcement_notify(invite_id); exception when insufficient_privilege then rejected:=true; end;
 if not rejected then raise exception 'Normal kullanıcı bildirim dağıtabildi.'; end if;
 if announcement_internal.valid_document('[{"type":"text"}]') or announcement_internal.valid_document('[{"type":"image","url":"javascript:alert(1)","alt":"x"}]') then raise exception 'Geçersiz belge kabul edildi.'; end if;
 if has_table_privilege('authenticated','announcement_internal.entries','SELECT') or has_table_privilege('anon','announcement_internal.reward_pools','SELECT') then raise exception 'Özel tablolara doğrudan erişim açık.'; end if;
 raise notice 'PASS: taslak, özel alıcı, anon, yönetici yetkisi, sürüm, zamanlama, ödül/tekrar/bütçe, davet, doğrulama, ACL';
end $$;
rollback;
select 'PASS: Bütün doğrulama değişiklikleri geri alındı.' as result;
